(function(ctx){
  var S=window.__INITIAL_STATE__;
  var u=function(x){var h=0;while(x&&typeof x==='object'&&'_rawValue' in x&&h<8){x=x._rawValue;h++;}return x;};
  var arr=function(v){v=u(v);return Array.isArray(v)?v:[];};
  var str=function(v){v=u(v);return v===undefined||v===null?'':String(v);};
  var norm=function(v){v=str(v);return v.indexOf('http://')===0?'https://'+v.slice(7):v;};
  var timeStr=function(v){v=u(v);if(v===undefined||v===null||v==='')return '';var n=Number(v);if(!isNaN(n)&&n>100000000000)return new Date(n).toISOString();return String(v);};
  var map=u((u(S.note)||{}).noteDetailMap)||{};
  var wanted=str(ctx.feedId);
  var keys=Object.keys(map);
  var entry=null;
  if(wanted&&map[wanted])entry=u(map[wanted]);
  if(!entry&&keys.length)entry=u(map[keys[0]]);
  if(!entry)return {note:null,comments:[],comment_total:0,error:'NOTE_STATE_MISSING'};
  var note=u(entry.note)||{};
  var bodyEl=document.querySelector('#detail-desc');
  var body='';var tags=[];
  if(bodyEl){
    tags=Array.from(bodyEl.querySelectorAll('a.tag'))
      .map(function(a){return (a.textContent||'').trim();})
      .filter(Boolean);
    var clone=bodyEl.cloneNode(true);
    Array.from(clone.querySelectorAll('a.tag')).forEach(function(el){
      if(el.parentNode)el.parentNode.removeChild(el);
    });
    body=(clone.textContent||'').replace(/\n{3,}/g,'\n\n').trim();
  }
  var inter=u(note.interactInfo||note.interact_info)||{};
  var user=u(note.user)||{};
  var avatar=u(user.avatar)||{};
  var images=arr(note.imageList||note.image_list).map(function(img){
    img=u(img);
    return norm(img.urlDefault||img.url_default||img.url||img.urlPre||img.url_pre);
  }).filter(Boolean);
  var list=arr((u(entry.comments)||{}).list);
  var comments=[];var seen={};
  for(var i=0;i<list.length;i++){
    var c=u(list[i]);
    if(!c)continue;
    var cid=str(c.id);
    if(!cid||seen[cid])continue;
    seen[cid]=1;
    var cu=u(c.userInfo||c.user_info)||{};
    var subs=arr(c.subComments||c.sub_comments).slice(0,3).map(function(sub){
      sub=u(sub);
      var su=u(sub.userInfo||sub.user_info)||{};
      return {
        comment_id:str(sub.id),
        content:str(sub.content),
        nickname:str(su.nickname),
        like_count:str(sub.likeCount||sub.like_count)
      };
    });
    comments.push({
      comment_id:cid,
      content:str(c.content),
      create_time:timeStr(c.createTime||c.create_time),
      ip_location:str(c.ipLocation||c.ip_location),
      like_count:str(c.likeCount||c.like_count),
      user_id:str(cu.userId||cu.user_id),
      nickname:str(cu.nickname),
      sub_comment_count:str(c.subCommentCount||c.sub_comment_count),
      sub_comments:subs
    });
  }
  var limit=Number(ctx.limitComments)||comments.length;
  return {
    note:{
      note_id:str(note.noteId||note.note_id)||wanted,
      title:str(note.title),
      desc:str(note.desc),
      body:body||str(note.desc),
      tags:tags,
      type:str(note.type),
      note_url:location.href,
      cover:images[0]||'',
      images:images,
      liked_count:str(inter.likedCount||inter.liked_count),
      collected_count:str(inter.collectedCount||inter.collected_count),
      comment_count:str(inter.commentCount||inter.comment_count),
      share_count:str(inter.shareCount||inter.share_count),
      author_id:str(user.userId||user.user_id),
      author_name:str(user.nickname||user.nickName),
      author_avatar:norm(avatar.url||avatar),
      publish_time:timeStr(note.time||note.createTime||note.create_time)
    },
    comments:comments.slice(0,limit),
    comment_total:comments.length,
    dom_comments:document.querySelectorAll('.parent-comment').length
  };
})
